    Gen2DexEntry(
        "SEEL",
        Gen2DexPage("SEA LION", 3, 7, 1980, "Although it can't\nwalk well on land,\nit is a graceful\n\nswimmer. It espe-\ncially loves being\nin frigid seas."),
        Gen2DexPage("SEA LION", 3, 7, 1980, "In daytime, it is\noften found asleep\non the seabed in\n\nshallow waters.\nIts nostrils close\nwhile it swims."),
        Gen2DexPage("SEA LION", 3, 7, 1980, "The light blue fur\nthat covers it\nkeeps it protected\n\nagainst the cold.\nIt loves iceberg-\nfilled oceans."),
    ),
    Gen2DexEntry(
        "DEWGONG",
        Gen2DexPage("SEA LION", 5, 7, 2650, "Its streamlined\nbody has little\ndrag in water.\n\nThe colder the\ntemperature, the\nfriskier it gets."),
