        Gen2DexPage("GAS", 4, 3, 2, "With its gas-like\nbody, it can sneak\ninto any place it\n\ndesires. However,\nit can be blown\naway by wind."),
        Gen2DexPage("GAS", 4, 3, 2, "Its thin body is\nmade of gas. It\ncan envelop an\n\nopponent of any\nsize and cause\nsuffocation."),
        Gen2DexPage("GAS", 4, 3, 2, "It wraps its op-\nponent in its gas-\nlike body, slowly\n\nweakening its prey\nby poisoning it\nthrough the skin."),
